async function fetchTable(n){let out=[];for(let p=0;p<10;p++){let{data,error}=await db.from(n).select('*').range(p*1000,p*1000+999);if(error)throw error;out.push(...data);if(data.length<1000)break;}return out}
async function reload(){const all=[...new Set(Object.values(tables))].filter(n=>n!=='audit_log'||me.role==='owner');const items=await Promise.all(all.map(async n=>[n,await fetchTable(n)]));D=Object.fromEntries(items);D.organization_features=await fetchTable('organization_features');D.attendance_locations=await fetchTable('attendance_locations');D.attendance_shift_summary=await fetchTable('attendance_shift_summary');D.attendance_policies=await fetchTable('attendance_policies');D.employee_notifications=await fetchTable('employee_notifications');D.organization_details=await fetchTable('organization_details');D.company_mail_settings=await fetchTable('company_mail_settings');D.payslip_branding=await fetchTable('payslip_branding');D.expense_proofs=await fetchTable('expense_proofs');D.payroll_profiles=await fetchTable('payroll_profiles');D.employee_alert_preferences=await fetchTable('employee_alert_preferences');D.attendance_breaks=await fetchTable('attendance_breaks');D.attendance_net_summary=await fetchTable('attendance_net_summary');await loadSupportData();render()}
async function firstLoginSetup(){
const {data:{session}}=await db.auth.getSession();
const m=session?.user?.user_metadata||{};
if(m.invitation_kind!=='employee'||m.password_set===true)return false;
$('root').innerHTML='<div class="auth"><form class="login" id="passwordSetup"><h1>Welcome to '+esc(m.company_name||'PeopleOS')+'</h1><p>Hello '+esc(m.full_name||'team member')+'! Your secure employee account is ready. Set your password to enter the HRMS.</p><div class="field"><label>New password (12+ characters)</label><input name="password" type="password" minlength="12" autocomplete="new-password" required></div><div class="field"><label>Confirm password</label><input name="confirm" type="password" minlength="12" autocomplete="new-password" required></div><p class="error hidden" id="setupError"></p><button type="submit">Activate my account</button><button type="button" class="white" id="setupSignout">Sign out</button></form></div>';
$('setupSignout').onclick=()=>db.auth.signOut().then(login);
$('passwordSetup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('password')!==f.get('confirm')){$('setupError').textContent='Passwords do not match';$('setupError').classList.remove('hidden');return}const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const {error}=await db.auth.updateUser({password:String(f.get('password')),data:{password_set:true}});if(error)throw error;await boot()}catch(err){$('setupError').textContent=err.message;$('setupError').classList.remove('hidden')}finally{b.disabled=false}};
return true;
}
function authLinkNotice(){
const search=new URLSearchParams(location.search),hash=new URLSearchParams(location.hash.slice(1));
const err=search.get('error_description')||hash.get('error_description');
if(!err)return false;
$('root').innerHTML='<div class="auth"><div class="login"><h1>Invitation link problem</h1><p>'+esc(err)+'</p><p class="notice">The link may have expired, been opened already, or redirected incorrectly. Contact HR for a new account setup link, or use Forgot password if your account has already been confirmed.</p><button id="linkSignIn">Go to sign in</button><button id="linkReset" class="white">Reset password</button></div></div>';
$('linkSignIn').onclick=()=>{history.replaceState(null,'',location.pathname);login()};
$('linkReset').onclick=()=>{history.replaceState(null,'',location.pathname);resetRequest()};
return true;
}
async function boot(){if(authLinkNotice())return;const {data:{session}}=await db.auth.getSession();if(!session){login();return}if(new URLSearchParams(location.search).get('flow')==='recovery'||new URLSearchParams(location.hash.replace(/^#/,'')).get('type')==='recovery'){await showPasswordRecovery();return}if(await firstLoginSetup())return;const {data:p,error}=await db.from('profiles').select('*').eq('user_id',session.user.id).maybeSingle();if(error||!p?.active){$('root').innerHTML='<div class="auth"><div class="login"><h1>Access pending</h1><p>Your company administrator must activate your employee profile.</p><button id="logout">Sign out</button></div></div>';$('logout').onclick=async()=>{await db.auth.signOut();login()};return}me=p;try{workspaceMode='company';platformAdmin=false;tab='Overview';await reload()}catch(e){notify(e.message,true);$('root').innerHTML='<div class="auth"><div class="login"><h1>Unable to load workspace</h1><p>'+esc(e.message)+'</p><button id="retry">Retry</button></div></div>';$('retry').onclick=boot}}
function login(){
$('root').innerHTML='<div class="auth"><form class="login" id="login"><h1>PeopleOS</h1><p>Secure workforce management</p><div class="field"><label>Work email</label><input id="email" type="email" autocomplete="username" required></div><div class="field"><label>Password</label><input id="password" type="password" autocomplete="current-password" required></div><p class="error hidden" id="err"></p><button type="submit">Sign in</button><button type="button" class="white" id="forgotPassword">Forgot password?</button><p class="small">New employee? Open the private invitation link sent to your email, then set your password.</p></form></div>';
$('login').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;let{error}=await db.auth.signInWithPassword({email:$('email').value,password:$('password').value});b.disabled=false;if(error){$('err').textContent=error.message;$('err').classList.remove('hidden')}else await boot()};
$('forgotPassword').onclick=()=>resetRequest();
}
function resetRequest(){
$('root').innerHTML='<div class="auth"><form class="login" id="requestReset"><h1>Reset your password</h1><p>Enter the email associated with your employee account. If that account is eligible, you will receive a secure password reset link.</p><div class="field"><label>Work email</label><input name="email" type="email" autocomplete="username" required></div><div class="notice hidden" id="resetNote"></div><div class="error hidden" id="resetError"></div><button type="submit">Email password reset link</button><button type="button" id="backToLogin" class="white">Back to sign in</button></form></div>';
$('backToLogin').onclick=login;
$('requestReset').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;const email=new FormData(e.target).get('email');try{const{error}=await db.auth.resetPasswordForEmail(String(email),{redirectTo:location.origin+'/?flow=recovery'});if(error)throw error;$('resetNote').classList.remove('hidden');$('resetNote').textContent='If this email can receive account messages, a password-reset link has been requested. Check your inbox and spam folder. Mail delivery depends on the configured email provider.';$('resetError').classList.add('hidden')}catch(err){$('resetError').classList.remove('hidden');$('resetError').textContent=err.message}finally{b.disabled=false}};
}
async function showPasswordRecovery(){
const{data:{session}}=await db.auth.getSession();if(!session){resetRequest();return}
$('root').innerHTML='<div class="auth"><form class="login" id="completeReset"><h1>Choose a new password</h1><p>Set a strong password for your PeopleOS account.</p><div class="field"><label>New password (12+ characters)</label><input name="password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label>Confirm password</label><input name="confirm" type="password" autocomplete="new-password" minlength="12" required></div><p class="error hidden" id="resetError"></p><button type="submit">Update password</button></form></div>';
$('completeReset').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),pw=String(f.get('password'));if(pw!==f.get('confirm')){$('resetError').textContent='The passwords do not match.';$('resetError').classList.remove('hidden');return}const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const{error}=await db.auth.updateUser({password:pw,data:{password_set:true}});if(error)throw error;history.replaceState(null,'',location.pathname);await db.auth.signOut();login();notify('Password changed. Please sign in with your new password.')}catch(err){$('resetError').textContent=err.message;$('resetError').classList.remove('hidden')}finally{b.disabled=false}};
}

const permitted=t=>{if(t==='Platform'||!allowedModule(t))return false;if(t==='Notifications')return true;if(t==='My Access')return me.role==='owner';if(t==='Company Mail')return me.role==='owner';let r=me.role;if(r==='team_leader')return ['Overview','Employees','Attendance','Corrections','Leave','Balances','Tasks','Expenses','Roster','Holidays','Announcements','My Profile'].includes(t);if(r==='employee')return ['Overview','Attendance','Corrections','Leave','Balances','Tasks','Expenses','Onboarding','Roster','Reviews','Payroll','Holidays','Announcements','My Profile'].includes(t);if(r==='manager')return !['Support','Recruitment','Candidates','Interviews','Settings','Activity','Payroll'].includes(t);if(r==='hr')return !['Settings','Activity'].includes(t);return r==='owner'};
function frame(body){let group='',unread=(D.employee_notifications||[]).filter(x=>!x.read_at).length;const icons={'Company Mail':'✉',Notifications:'◉',Support:'✉',Recruitment:'♙',Candidates:'♙',Interviews:'◷',Onboarding:'☑',Shifts:'◷',Roster:'▦',Platform:'▦',Overview:'◫',Employees:'♙',Attendance:'◷',Corrections:'✎',Leave:'▤',Balances:'▥',Tasks:'☑',Expenses:'▣',Assets:'◇',Reviews:'☆',Payroll:'▦',Holidays:'▧',Announcements:'◉',Settings:'⚙',Activity:'≡',Reports:'▥','My Profile':'◌','My Access':'▤'};$('root').innerHTML='<div class="layout" id="appLayout"><div class="mobile-overlay" id="menuOverlay"></div><aside class="side"><div class="logo">People<em>OS</em><div style="font-size:9px;font-weight:500;letter-spacing:1.4px;color:#8396b4;margin-top:3px">WORKFORCE INTELLIGENCE</div></div><div class="side-scroll" id="sideNav">'+nav.filter(([n])=>permitted(n)).map(([n,g])=>(group===g?'':(group=g,'<div class="group">'+g+'</div>'))+'<button class="nav '+(tab===n?'active':'')+'" data-tab="'+n+'"><span class="ni">'+(icons[n]||'◦')+'</span>'+(me.role==='employee'?({Attendance:'My Attendance',Roster:'My Roster',Tasks:'My Tasks',Leave:'My Leave',Payroll:'My Payslips'}[n]||n):(['manager','team_leader'].includes(me.role)&&n==='Employees'?'My Team':n))+(n==='Notifications'&&unread?' <span class="notice-count">'+unread+'</span>':'')+'</button>').join('')+'</div><div class="mebox"><strong>'+esc(me.full_name)+'</strong><p>'+esc(fmt(me.role).toUpperCase())+'</p>'+''+'<button class="ghost width100" id="logout">Sign out</button></div></aside><div class="content"><div class="top"><div class="top-name"><button class="mobile-trigger" id="mobileMenu" aria-label="Open navigation">☰</button><div><div class="crumb">PeopleOS / '+esc(tab)+'</div><h1>'+esc(tab==='Overview'?(me.role==='manager'||me.role==='team_leader'?'Team overview':me.role==='employee'?'My workspace':'Workforce overview'):tab)+'</h1></div></div><div class="topright"><span class="org-pill">●  '+esc(D.company_settings?.[0]?.company_name||'Your company')+'</span><span class="date">'+new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})+'</span><button class="white" id="refresh">↻ Refresh</button><button class="ghost" id="toplogout">Sign out</button></div></div><div id="main">'+body+'</div><p class="footerhint">PeopleOS Workforce Intelligence · Live records · Access controlled</p></div></div>';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigateTo(b.dataset.tab));['logout','toplogout'].forEach(x=>{$(x).onclick=async()=>{await db.auth.signOut();me=null;login()}});$('refresh').onclick=async()=>{try{await reload();notify('Records refreshed')}catch(e){notify(e.message,true)}};if($('mobileMenu'))$('mobileMenu').onclick=()=>$('appLayout').classList.add('menu-open');if($('menuOverlay'))$('menuOverlay').onclick=()=>$('appLayout').classList.remove('menu-open');}
const stat=(a,b,c)=>'<div class="card"><span>'+a+'</span><b>'+b+'</b><small>'+c+'</small></div>';
function breakSummary(a){if(!a?.id)return '';let entries=(D.attendance_breaks||[]).filter(x=>x.attendance_id===a.id),active=entries.some(x=>!x.ended_at),minutes=entries.reduce((sum,x)=>sum+Math.max(0,(new Date(x.ended_at||Date.now())-new Date(x.started_at))/60000),0),total=a.check_in?Math.max(0,(new Date(a.check_out||Date.now())-new Date(a.check_in))/60000):0,net=Math.max(0,total-minutes);return '<div class="break-strip"><strong>'+(active?'On break':'Break time')+'</strong><span class="muted small">Breaks '+Math.round(minutes)+' min · Net '+(net/60).toFixed(2)+' hr</span>'+(a.check_in&&!a.check_out?'<button class="white" type="button" id="breakAction">'+(active?'End break':'Start break')+'</button>':'')+'</div>'}
async function recordBreak(){const record=(D.attendance||[]).find(x=>x.user_id===me.user_id&&x.work_date===localDate());if(!record?.check_in||record.check_out)throw Error('You must be checked in and not checked out');let active=(D.attendance_breaks||[]).some(x=>x.attendance_id===record.id&&!x.ended_at),action=active?'end':'start';let {error}=await db.rpc('record_attendance_break',{p_action:action});if(error)throw error;notify(action==='start'?'Break started':'Break finished');await reload()}
function dash(){if(me.role==='employee'){let d=localDate(),id=me.user_id,a=(D.attendance||[]).find(v=>v.user_id===id&&v.work_date===d),t=(D.tasks||[]).filter(v=>v.assigned_to===id&&v.status!=='done'),q=(D.leave_requests||[]).filter(v=>v.user_id===id),e=(D.leave_entitlements||[]).filter(v=>v.user_id===id&&v.calendar_year===+d.slice(0,4)),s=(D.work_shifts||[]).filter(v=>v.user_id===id&&v.shift_date>=d&&v.status!=='cancelled');let balances=e.map(v=>{let y=Number(v.calendar_year),first=y+'-01-01',last=y+'-12-31',weekends=D.attendance_policies?.[0]?.weekend_days||[0,6],holiday=new Set((D.holidays||[]).map(k=>k.holiday_date));let used=q.filter(k=>k.leave_type===v.leave_type&&k.status==='approved').reduce((n,k)=>{let s=k.start_date>first?k.start_date:first,e=k.end_date<last?k.end_date:last;if(s>e)return n;for(let d=new Date(s+'T12:00:00Z'),max=new Date(e+'T12:00:00Z');d<=max;d.setUTCDate(d.getUTCDate()+1)){let key=d.toISOString().slice(0,10);if(!weekends.includes(d.getUTCDay())&&!holiday.has(key))n++}return n},0);return '<p><b>'+esc(fmt(v.leave_type))+': '+(Number(v.days)-used)+' days left</b><small class="muted"> · Allocated '+v.days+' / Used '+used+'</small></p>'}).join('');return '<div class="banner"><h2>Hello, '+esc(me.full_name.split(' ')[0])+'.</h2><p>Your workday, leave and schedule</p></div><div class="s-dashboard">'+metric('My attendance',a?.check_out?'Complete':a?.check_in?(D.attendance_breaks||[]).some(x=>x.attendance_id===a.id&&!x.ended_at)?'On break':'Working':'Not checked in','Today','◷')+metric('My tasks',t.length,'Outstanding','☑')+metric('Leave requests',q.filter(v=>v.status==='pending').length,'Pending','▤')+metric('Shifts ahead',s.length,'Upcoming','▦')+'</div><div class="split"><section class="panel"><h2>Today’s attendance</h2><p>In '+esc(stamp(a?.check_in))+'<br>Out '+esc(stamp(a?.check_out))+'<br><b>Gross hours '+(a?.check_in?Math.max(0,((new Date(a?.check_out||Date.now()))-new Date(a.check_in))/36e5).toFixed(2):'0.00')+'</b></p><button id="clock" '+(a?.check_out?'disabled':'')+'>'+(a?.check_out?'Complete':a?.check_in?'Check out':'Check in')+'</button>'+breakSummary(a)+'</section><section class="panel"><h2>My leave balance</h2>'+(balances||'<p>Not allocated by HR</p>')+'<p class="muted small">Balance excludes configured weekends and holidays. Special leave and half-days require HR review.</p><button class="white tiny" data-goto="Balances">Details</button></section></div><div class="split"><section class="panel"><h2>My tasks</h2>'+gridRows('Tasks',t.slice(0,4))+'</section><section class="panel"><h2>My roster</h2>'+(s.length?s.slice(0,3).map(v=>'<p>'+esc(v.shift_date)+' · '+esc(v.starts_at.slice(0,5))+'–'+esc(v.ends_at.slice(0,5))+'</p>').join(''):'<p>No shifts assigned.</p>')+'</section></div>'}const d=localDate(),staff=(D.profiles||[]).filter(x=>x.active),a=D.attendance||[],today=a.filter(x=>x.work_date===d),tasks=D.tasks||[],leave=D.leave_requests||[],pending=leave.filter(x=>x.status==='pending'),open=tasks.filter(x=>x.status!=='done'),overdue=open.filter(x=>x.due_date&&x.due_date<d),mine=today.find(x=>x.user_id===me.user_id),ann=(D.announcements||[]).filter(x=>x.published).slice(-2).reverse(),shiftIssues=a.filter(x=>x.check_in&&!x.check_out&&x.work_date<d).length;const links=[['Employees','Employees'],['Attendance','Attendance'],['Tasks','Tasks'],['Leave','Leave approvals'],['Payroll','Payroll'],['Reports','Reports']].filter(x=>permitted(x[0]));return '<div class="banner"><h2>'+esc(D.company_settings?.[0]?.company_name||'Company')+' overview</h2><p>Workforce activity and priorities · '+esc(d)+'</p></div><div class="s-dashboard">'+metric('Active employees',staff.length,'Workforce','♙')+metric('Checked in today',today.length,'Recorded punches','◷')+metric('Approvals waiting',pending.length,'Leave requests','▤')+metric('Tasks overdue',overdue.length,'Action required','☑')+'</div><div class="split"><section class="panel"><div class="panelhead"><h2>Work requiring attention</h2><button class="white tiny" data-goto="Tasks">All tasks</button></div><div class="boxline"><span>Missing checkout</span><b>'+shiftIssues+'</b></div><div class="boxline"><span>Pending leave</span><b>'+pending.length+'</b></div><div class="boxline"><span>Open tasks</span><b>'+open.length+'</b></div>'+(open.length?'<div style="margin-top:12px">'+gridRows('Tasks',open.slice(0,3))+'</div>':'<p class="muted small">No outstanding tasks.</p>')+'</section><section class="panel"><div class="panelhead"><h2>My attendance</h2>'+tag(mine?.check_out?'Completed':mine?.check_in?(D.attendance_breaks||[]).some(x=>x.attendance_id===mine.id&&!x.ended_at)?'On break':'Working':'Not checked in')+'</div><div class="profile-info"><div class="profile-cell"><label>Check-in</label><strong>'+esc(stamp(mine?.check_in))+'</strong></div><div class="profile-cell"><label>Check-out</label><strong>'+esc(stamp(mine?.check_out))+'</strong></div><div class="profile-cell"><label>Net worked hours</label><strong>'+(mine?.check_in?(((D.attendance_net_summary||[]).find(x=>x.id===mine.id)?.net_worked_minutes||0)/60).toFixed(2)+' hr':'—')+'</strong></div></div><button id="clock" style="width:100%;margin-top:12px" '+(mine?.check_out?'disabled':'')+'>'+(mine?.check_out?'Shift completed':mine?.check_in?'Check out':'Check in')+'</button>'+breakSummary(mine)+'<p class="muted small">GPS is captured only when you confirm a punch.</p></section></div><div class="panel"><div class="panelhead"><h2>Quick access</h2></div><div class="quick-grid">'+links.map(([k,label])=>'<button class="quick-link" data-goto="'+k+'">'+label+'</button>').join('')+'</div></div>'+(ann.length?'<div class="panel"><div class="panelhead"><h2>Company announcements</h2><button class="white tiny" data-goto="Announcements">View all</button></div>'+ann.map(x=>'<div class="announce"><strong>'+esc(x.title)+'</strong><p>'+esc(x.body)+'</p></div>').join('')+'</div>':'')}
const cols={Recruitment:[['title','Position'],['department','Department'],['location','Location'],['headcount','Openings'],['status','Status']],Candidates:[['full_name','Candidate'],['email','Email'],['position','Position'],['stage','Stage']],Interviews:[['candidate_id','Candidate'],['interviewer_id','Interviewer'],['scheduled_at','Date/time'],['status','Status']],Onboarding:[['user_id','Employee'],['title','Checklist item'],['due_date','Due date'],['status','Status']],Shifts:[['user_id','Employee'],['shift_date','Date'],['starts_at','Start'],['ends_at','End'],['status','Status']],Employees:[['full_name','Employee'],['email','Email'],['department','Department'],['job_title','Position'],['manager_id','Manager'],['role','Role'],['active','Status']],Attendance:[['user_id','Employee'],['work_date','Date'],['check_in','Check-in'],['check_out','Check-out'],['hours','Gross'],['net_hours','Net'],['break_minutes','Breaks'],['shift_assessment','Shift review'],['location_in','Check-in GPS'],['location_out','Check-out GPS']],Corrections:[['user_id','Employee'],['work_date','Date'],['reason','Reason'],['status','Status']],Leave:[['user_id','Employee'],['leave_type','Type'],['start_date','From'],['end_date','To'],['status','Status']],Balances:[['user_id','Employee'],['calendar_year','Year'],['leave_type','Type'],['days','Allocated']],Tasks:[['title','Task'],['assigned_to','Assigned'],['due_date','Deadline'],['priority','Priority'],['status','Status']],Expenses:[['user_id','Employee'],['title','Claim'],['amount','Amount'],['expense_date','Date'],['status','Status']],Assets:[['asset_tag','Asset tag'],['name','Equipment'],['category','Category'],['assigned_to','Assigned'],['status','Status']],Reviews:[['user_id','Employee'],['period','Period'],['rating','Rating'],['status','Visibility']],Payroll:[['user_id','Employee'],['month','Month'],['basic','Basic'],['status','Status']],Holidays:[['holiday_date','Date'],['name','Holiday'],['region','Region']],Announcements:[['title','Announcement'],['body','Content'],['created_at','Date']],Activity:[['created_at','When'],['actor_id','Actor'],['operation','Action'],['table_name','Module'],['row_id','Record']]};
function display(row,key){if(key==='net_hours'||key==='break_minutes'){let s=(D.attendance_net_summary||[]).find(x=>x.id===row.id);return s?(key==='net_hours'?(Number(s.net_worked_minutes||0)/60).toFixed(2):Number(s.break_minutes||0)+' min'):'—'}if(key==='shift_assessment'){const a=(D.attendance_shift_summary||[]).find(x=>x.id===row.id);if(!a)return 'Not assessed';return '<strong>'+esc(fmt(a.arrival_status))+'</strong>'+(a.left_early?'<small class="geo-accuracy">Early checkout</small>':'')+(a.short_shift?'<small class="geo-accuracy">Below minimum shift</small>':'')+(a.overtime_minutes?'<small class="geo-accuracy">Overtime '+a.overtime_minutes+' min</small>':'')}if(key==='location_in'||key==='location_out'){const event=key==='location_in'?'check_in':'check_out';const loc=(D.attendance_locations||[]).find(x=>x.attendance_id===row.id&&x.event_type===event);if(!loc)return '<span class="muted">Not recorded</span>';const lat=Number(loc.latitude),lng=Number(loc.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))return 'Unavailable';const link='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(lat+','+lng);const place=[loc.area_name,loc.city_name,loc.region_name].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', ');return '<strong class="geo-area">'+esc(place||'GPS pin saved · locality unavailable')+'</strong><a href="'+link+'" target="_blank" rel="noopener noreferrer" class="geo-link">View exact GPS pin</a><small class="geo-accuracy">±'+Math.round(loc.accuracy_m)+'m · '+esc(stamp(loc.captured_at))+'</small>'}let v=row[key];if(key==='days'){let y=+row.calendar_year,used=(D.leave_requests||[]).filter(x=>x.user_id===row.user_id&&x.leave_type===row.leave_type&&x.status==='approved').reduce((n,x)=>{let s=Math.max(Date.parse(x.start_date),Date.UTC(y,0,1)),e=Math.min(Date.parse(x.end_date),Date.UTC(y,11,31));return n+Math.max(0,Math.round((e-s)/864e5)+1)},0);return '<strong>'+esc(Number(v)-used)+' remaining</strong><small class="geo-accuracy">Allocated '+esc(v)+' · Approved '+used+'</small>'}if(key==='candidate_id')return esc((D.candidates||[]).find(c=>c.id===v)?.full_name||'Candidate');if(['user_id','assigned_to','manager_id','interviewer_id','author_id','actor_id'].includes(key))return esc(name(v));if(key==='hours')return esc(hour(row));if(key==='amount'||key==='basic')return esc(money(v,row.currency));if(key==='active')return tag(v?'Active':'Inactive');if(['status','role','priority','stage'].includes(key))return tag(v);if(['check_in','check_out','created_at','scheduled_at'].includes(key))return esc(stamp(v));return esc(typeof v==='string'&&v.length>65?v.slice(0,65)+'…':v??'—')}
function gridRows(t,rows){const headers=cols[t]||[];return '<div class="scroll"><table><thead><tr>'+headers.map(([,title])=>'<th>'+title+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>'+ (rows.length?rows.map(row=>'<tr>'+headers.map(([key])=>'<td>'+display(row,key)+'</td>').join('')+'<td>'+actions(t,row)+'</td></tr>').join(''):'<tr><td colspan="'+(headers.length+1)+'" class="empty">No records found</td></tr>')+'</tbody></table></div>'}
function actions(t,r){let out=[];const btn=(text,action,val,kind='ghost')=>'<button class="tiny '+kind+'" data-act="'+action+'" data-id="'+esc(r.id||r.user_id)+'" data-val="'+esc(val||'')+'">'+text+'</button>';if(t==='Employees'&&isStaff()){out.push(btn('Edit','edit',''));if(r.role!=='owner'&&r.user_id!==me.user_id)out.push(btn(r.active?'Deactivate':'Reactivate','employeeState',r.active?'deactivate':'reactivate',r.active?'negative':'ghost'))}if(t==='Leave'&&r.status==='pending'&&r.user_id===me.user_id)out.push(btn('Edit my request','editLeave',''));if(['Recruitment','Candidates','Interviews','Onboarding','Shifts'].includes(t)&&isStaff())out.push(btn('Edit','editGeneric',''));if(t==='Leave'&&['owner','hr','manager'].includes(me.role)&&r.status==='pending'&&r.user_id!==me.user_id){out.push(btn('Approve','state','approved'),btn('Reject','state','rejected','negative'))}if(t==='Corrections'&&isStaff()&&r.status==='pending'&&r.user_id!==me.user_id){out.push(btn('Approve','state','approved'),btn('Reject','state','rejected','negative'))}if(t==='Expenses'){let attached=(D.expense_proofs||[]).find(x=>x.expense_id===r.id);if(attached)out.push(btn('View proof','viewProof',''));else if(r.user_id===me.user_id&&r.status==='pending')out.push(btn('Attach proof','attachProof',''));}if(t==='Expenses'&&isStaff()&&r.user_id!==me.user_id){if(r.status==='pending')out.push(btn('Approve','state','approved'),btn('Reject','state','rejected','negative'));else if(r.status==='approved')out.push(btn('Reimburse','state','reimbursed'))}if(t==='Tasks'&&(r.assigned_to===me.user_id||isManager()))out.push(btn('Change status','task',''));if(t==='Tasks'&&isManager())out.push(btn('Edit / Reassign','taskEdit',''));if(t==='Candidates'&&isStaff())out.push(btn('Hiring stage','candidateStage',''));if(t==='Payroll'&&me.role==='owner'&&r.status!=='paid')out.push(btn(r.status==='draft'?'Approve':'Mark paid','state',r.status==='draft'?'approved':'paid'));if(t==='Payroll'&&r.status!=='draft')out.push(btn('Payslip','payslip',''));if(t==='Payroll'&&isStaff()&&['approved','paid'].includes(r.status)&&D.company_mail_settings?.[0]?.verification_status==='verified')out.push(btn('Email payslip','emailPayslip',''));return out.join(' ')||'<span class="muted">—</span>'}
function permittedNew(t){if(['Leave','Corrections','Expenses'].includes(t))return true;if(['Employees','Recruitment','Candidates','Interviews','Onboarding','Shifts','Balances','Assets','Reviews','Payroll','Holidays','Announcements'].includes(t))return isStaff();if(t==='Tasks')return isManager();return false}
function attendanceIntro(list,all){let d=localDate(),today=all.filter(x=>x.work_date===d),open=all.filter(x=>x.check_in&&!x.check_out),closed=list.filter(x=>x.check_in&&x.check_out),hours=closed.reduce((n,x)=>{let s=(D.attendance_net_summary||[]).find(y=>y.id===x.id);return n+(s?Number(s.net_worked_minutes||0)/60:Math.max(0,(new Date(x.check_out)-new Date(x.check_in))/36e5))},0);return '<div class="attendance-summary">'+metric('Present today',today.length,'Checked in','◷')+metric('Missing checkout',open.filter(x=>x.work_date<d).length,'Previous days','!')+metric('Completed shifts',closed.length,'Recorded','✓')+metric('Worked hours',hours.toFixed(1),'Selected period · net','◶')+'</div><section class="panel"><h2>Attendance controls</h2><p class="muted small">GPS timestamps and shift assessments are server-verified. Missing punches require HR correction. An area name is approximate; the map uses stored coordinates.</p><button class="white" data-goto="Corrections">Request correction</button>'+breakSummary((D.attendance||[]).find(x=>x.user_id===me.user_id&&x.work_date===localDate()))+'</section>'}
function payrollAdmin(){if(!['owner','hr'].includes(me.role))return '';const workers=(D.profiles||[]).filter(x=>x.active),salary=D.payroll_profiles||[],brand=D.payslip_branding?.[0]||{},styles={classic:'Classic Corporate',modern:'Executive Blue',compact:'Compact Minimal',code:'Custom HTML & CSS'},name=styles[brand.template_style||'classic']||styles.classic;return '<div class="panel"><div class="panelhead"><div><h2>Enterprise payroll</h2><p class="muted small">Salary profiles · Monthly payroll · Payslip templates</p></div><div class="actionrow"><button class="white" id="payBrand">View / change payslip template</button></div></div><div class="template-status"><div class="template-status-title"><small>ACTIVE PAYSLIP TEMPLATE</small><strong>'+esc(name)+'</strong></div><div class="template-status-meta"><span>'+(D.payslip_branding?.length?'Saved to company':'Default design')+'</span><span>Logo: '+((brand.logo_path||brand.logo_url)?'Uploaded':'Not uploaded')+'</span><span>Seal: '+((brand.seal_path||brand.seal_url)?'Uploaded':'Not uploaded')+'</span><span>Last saved: '+esc(brand.updated_at?stamp(brand.updated_at):'Not yet')+'</span></div><p class="muted small">This design is used when you open or print any company payslip. Employee salary values remain separate and unchanged.</p></div><div class="actionrow"><label class="small">Pay month <input id="payMonth" type="month" value="'+localDate().slice(0,7)+'"></label><button id="payBulk">Generate monthly drafts</button><button class="white" id="downloadSalaryCsv">Download salary CSV</button><button class="white" id="importSalaryCsv">Import salary CSV</button><input type="file" id="salaryFile" accept=".csv,text/csv" style="display:none"><span class="muted small">'+salary.length+' salary templates configured</span></div><div class="scroll"><table><thead><tr><th>Employee</th><th>Monthly salary</th><th>Action</th></tr></thead><tbody>'+workers.map(e=>{let s=salary.find(x=>x.user_id===e.user_id);return '<tr><td>'+esc(e.full_name)+'</td><td>'+(s?esc(money(s.basic,s.currency))+' basic · '+esc(money(s.allowances,s.currency))+' allowances':'<span class="tag warn">Not configured</span>')+'</td><td><button class="white tiny" data-editpay="'+esc(e.user_id)+'">'+(s?'Edit salary':'Set salary')+'</button></td></tr>'}).join('')+'</tbody></table></div></div>'}
function paySalary(uid){let e=(D.profiles||[]).find(x=>x.user_id===uid),s=(D.payroll_profiles||[]).find(x=>x.user_id===uid)||{};if(!e)return;modal('Salary structure — '+e.full_name,'<form><p class="muted small">Save recurring monthly amounts. Existing approved or paid payroll will not be changed.</p><div class="formgrid"><div class="field"><label>Currency</label><select name="currency">'+['INR','GBP','USD','EUR','AED'].map(c=>'<option '+((s.currency||'INR')===c?'selected':'')+'>'+c+'</option>').join('')+'</select></div>'+[['basic','Monthly basic'],['allowances','Monthly allowances'],['deductions','Monthly deductions']].map(([k,l])=>'<div class="field"><label>'+l+'</label><input name="'+k+'" type="number" min="0" max="999999999" step="0.01" value="'+esc(s[k]??0)+'" required></div>').join('')+'</div><button type="submit">Save salary</button></form>',async x=>{let a={organization_id:me.organization_id,user_id:uid,currency:x.currency,basic:Number(x.basic),allowances:Number(x.allowances),deductions:Number(x.deductions)};if([a.basic,a.allowances,a.deductions].some(v=>!Number.isFinite(v)||v<0))throw Error('Invalid salary components');let{error}=await db.from('payroll_profiles').upsert(a,{onConflict:'organization_id,user_id'});if(error)throw error})}
const BRAND_BUCKET='peopleos-company-branding';
function validBrandImage(f){if(!f||!f.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2097152)throw Error('Use PNG/JPG/WebP up to 2 MB');return f}
async function uploadBrandImage(file){file=validBrandImage(file);if(!file)return null;let ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[file.type],path=me.organization_id+'/'+me.user_id+'/'+crypto.randomUUID()+'.'+ext;let {error}=await db.storage.from(BRAND_BUCKET).upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path}
async function signedBrandImage(path,url){if(!path)return url||'';const {data,error}=await db.storage.from(BRAND_BUCKET).createSignedUrl(path,120);if(error||!data?.signedUrl)throw Error('Company image access denied: '+(error?.message||'No secure link'));const response=await fetch(data.signedUrl,{cache:'no-store'});if(!response.ok)throw Error('Company image download failed (HTTP '+response.status+')');const blob=await response.blob();if(!['image/png','image/jpeg','image/webp'].includes(blob.type)||blob.size>2097152)throw Error('Uploaded branding image is invalid');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(Error('Could not decode branding image'));reader.readAsDataURL(blob)})}
function templatePreview(s){let name={classic:'Classic Corporate',modern:'Executive Blue',compact:'Compact Minimal',code:'Code Design'};return '<div class="template-preview '+esc(s)+'"><div class="pv-head"><b>ACME COMPANY (SAMPLE)</b><span>PAYSLIP</span></div><h3>'+esc(name[s]||name.classic)+'</h3><p>Alex Example · October 2026</p><div class="pv-grid"><span>Basic</span><b>₹40,000</b><span>Allowances</span><b>₹5,000</b><span>Deductions</span><b>₹2,500</b></div><div class="pv-net">Net Pay <b>₹42,500</b></div><small class="muted">Signature / seal if company supplies one</small></div>'}
const CUSTOM_PREFIX='PO_CUSTOM_TEMPLATE_V1:';
const SAMPLE_CODE='<section class="slip"><header class="slip-head"><h2>{{company_name}}</h2><p>{{company_address}}</p></header><h1>SALARY PAYSLIP</h1><p>Employee: <b>{{employee_name}}</b> | ID: {{employee_id}}</p><p>Period: {{period}} | Department: {{department}}</p><table><tr><th>Earnings</th><th>Amount</th></tr><tr><td>Basic salary</td><td>{{basic}}</td></tr><tr><td>Allowances</td><td>{{allowances}}</td></tr><tr><th>Deductions</th><th>{{deductions}}</th></tr></table><h2>Net Pay: {{net_pay}}</h2><footer>{{signatory_name}} | Company seal: {{seal_label}}</footer></section>';
const SAMPLE_CSS='.slip{font:14px Arial,sans-serif;color:#152d54;padding:30px;max-width:760px;margin:auto;background:#fff}.slip-head{border-bottom:4px solid #3263cc}.slip h1{font-size:23px}.slip table{width:100%;border-collapse:collapse;margin:25px 0}.slip td,.slip th{padding:13px;border-bottom:1px solid #dce4ef;text-align:left}.slip footer{margin-top:40px;color:#586d88}';
function decodedPayslipNote(value){if(!String(value||'').startsWith(CUSTOM_PREFIX))return {note:String(value||''),html:SAMPLE_CODE,css:SAMPLE_CSS};try{let x=JSON.parse(String(value).slice(CUSTOM_PREFIX.length));return {note:String(x.note||''),html:String(x.html||SAMPLE_CODE),css:String(x.css||SAMPLE_CSS)}}catch{return {note:'',html:SAMPLE_CODE,css:SAMPLE_CSS}}}
function customTemplateSafeCSS(css){let x=String(css||'').slice(0,12000);if(/@import|@font-face|@namespace|url\s*\(|expression\s*\(|behavior\s*:|-moz-binding|\\|<|>|javascript:/i.test(x))throw Error('CSS imports, URLs, external resources and active content are not supported');return x}
