async function payBulk(){let m=$('payMonth')?.value;if(!/^\d{4}-\d{2}$/.test(m||''))throw Error('Select month');if(!confirm('Generate draft payroll for '+m+'? Existing monthly records will not be overwritten; no payments or emails will be sent.'))return;let{data,error}=await db.rpc('generate_monthly_payroll_drafts',{p_month:m+'-01'});if(error)throw error;notify('Created '+Number(data?.[0]?.created_count||0)+' monthly draft payslips, skipped '+Number(data?.[0]?.skipped_count||0));await reload()}
function parseSalaryCSV(text){let rows=[],r=[],f='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){f+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){r.push(f);f=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;r.push(f);if(r.some(x=>x.trim()))rows.push(r);r=[];f=''}else f+=c}if(quoted)throw Error('Invalid CSV quotes');r.push(f);if(r.some(x=>x.trim()))rows.push(r);return rows}
function downloadSalaryCSV(){let headers=['employee_code','basic','allowances','deductions','currency'],rows=[headers],quote=s=>'"'+String(s??'').replaceAll('"','""').replace(/[\r\n]/g,' ').replace(/^([=+@-])/,'\'$1')+'"';for(let e of (D.profiles||[]).filter(x=>x.active&&x.employee_code)){let p=(D.payroll_profiles||[]).find(x=>x.user_id===e.user_id);rows.push([e.employee_code,p?.basic??'',p?.allowances??0,p?.deductions??0,p?.currency||'INR'])}let b=new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='peopleos-salary-'+localDate()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importSalaryCSV(file){if(!file)return;if(file.size>2097152)throw Error('Maximum CSV size is 2 MB');let rows=parseSalaryCSV((await file.text()).replace(/^\ufeff/,''));if(rows.length<2||rows.length>501)throw Error('File must contain 1 to 500 employee rows');let headers=rows[0].map(v=>v.trim().toLowerCase()),idx=k=>headers.indexOf(k);if(idx('employee_code')<0||idx('basic')<0)throw Error('CSV must include employee_code and basic columns');let people=new Map(),dupes=new Set();for(let p of (D.profiles||[]).filter(x=>x.active&&x.employee_code)){let code=p.employee_code.trim().toLowerCase();if(people.has(code))dupes.add(code);people.set(code,p)}let used=new Set(),values=[],moneyVal=(v,label)=>{if(!/^\d+(\.\d{1,2})?$/.test(v))throw Error('Invalid '+label+' value '+v);return Number(v)};for(let r of rows.slice(1)){let get=k=>idx(k)>=0?String(r[idx(k)]??'').trim():'',code=get('employee_code'),basic=get('basic');if(!code||!basic)continue;let key=code.toLowerCase();if(used.has(key)||dupes.has(key))throw Error('Duplicate employee code '+code);used.add(key);let employee=people.get(key);if(!employee)throw Error('Unknown or inactive employee code '+code);let currency=(get('currency')||'INR').toUpperCase();if(!['INR','GBP','USD','EUR','AED'].includes(currency))throw Error('Unsupported currency '+currency);values.push({organization_id:me.organization_id,user_id:employee.user_id,basic:moneyVal(basic,'basic'),allowances:moneyVal(get('allowances')||'0','allowances'),deductions:moneyVal(get('deductions')||'0','deductions'),currency})}if(!values.length)throw Error('No valid rows to import');if(!confirm('Import salary structures for '+values.length+' employees? Existing salary templates for these employees will be updated. Approved payroll will not change.'))return;let{error}=await db.from('payroll_profiles').upsert(values,{onConflict:'organization_id,user_id'});if(error)throw error;notify(values.length+' salary profiles imported');await reload()}
function leaveApprovalInbox(){if(!['owner','hr','manager'].includes(me.role))return '';let rows=(D.leave_requests||[]).filter(x=>x.status==='pending'&&x.user_id!==me.user_id&&(D.profiles||[]).some(p=>p.user_id===x.user_id)),count=rows.length;return '<div class="panel leave-approval-box"><div class="panelhead"><div><h2>Team leave approvals</h2><p class="muted small">Only pending requests within your authorized reporting scope are shown. A reviewer cannot approve their own leave.</p></div><span class="tag '+(count?'warn':'good')+'">'+count+' pending</span></div>'+(count?'<div class="scroll"><table><thead><tr><th>Employee</th><th>Leave</th><th>Dates</th><th>Decision</th></tr></thead><tbody>'+rows.slice(0,30).map(v=>'<tr><td>'+esc(name(v.user_id))+'</td><td>'+esc(fmt(v.leave_type))+'</td><td>'+esc(v.start_date)+' – '+esc(v.end_date)+'</td><td><div class="actionrow"><button class="tiny" data-leave-decision="approved" data-id="'+esc(v.id)+'">Approve</button><button class="tiny negative" data-leave-decision="rejected" data-id="'+esc(v.id)+'">Reject</button></div></td></tr>').join('')+'</tbody></table></div>':'<p class="muted small">No team leave requests awaiting your decision.</p>')+'</div>'}
async function decideTeamLeave(id,status){if(!['approved','rejected'].includes(status))throw Error('Invalid decision');let request=(D.leave_requests||[]).find(x=>x.id===id);if(!request||request.status!=='pending'||request.user_id===me.user_id)throw Error('This leave request is not eligible for your approval');if(!confirm((status==='approved'?'Approve':'Reject')+' '+name(request.user_id)+' leave from '+request.start_date+' to '+request.end_date+'?'))return;let{data,error}=await db.from('leave_requests').update({status}).eq('id',id).eq('status','pending').select('id,status,reviewed_by,reviewed_at').single();if(error)throw error;if(data.status!==status||!data.reviewed_by)throw Error('Approval was not recorded correctly');notify('Leave '+status+' and employee notified.');await reload()}
function genericPage(){let t=tab,n=tables[t],all=D[n]||[],list=all.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||String(t==='Employees'?(r.active?'active':'inactive'):(r.status||'')).toLowerCase()===filter));let min=new Date(Date.now()-Number(dateRange||30)*864e5).toISOString().slice(0,10);if(t==='Attendance'&&dateRange!=='all')list=list.filter(r=>r.work_date>=min);let summary='Showing '+list.length+' of '+all.length+' accessible records';return (t==='Attendance'?attendanceIntro(list,all):t==='Payroll'?payrollAdmin():t==='Leave'?leaveApprovalInbox():'')+'<div class="panel"><div class="panelhead"><div><h2>'+esc(t)+' register</h2><p class="muted small">'+summary+'</p></div><div class="actionrow"><input id="search" placeholder="Search any field" value="'+esc(search)+'"><select id="filter"><option value="all">All statuses</option>'+['pending','approved','rejected','done','draft','paid','active','inactive','in_progress','reimbursed'].map(s=>'<option '+(filter===s?'selected':'')+'>'+s+'</option>').join('')+'</select>'+(t==='Attendance'?'<select id="range">'+['7','30','90','all'].map(k=>'<option value="'+k+'" '+(dateRange===k?'selected':'')+'>'+ (k==='all'?'All time':k+' days')+'</option>').join('')+'</select>':'')+'<button class="white" id="export">Export CSV</button>'+(permittedNew(t)?'<button id="create">+ '+(t==='Employees'?'Invite employee':t==='Recruitment'?'New vacancy':'New '+t.slice(0,-1))+'</button>':'')+'</div></div>'+gridRows(t,list)+'</div>'}
