function settings(){const x=D.company_settings?.[0];return '<div class="panel settings-panel"><h2>Organisation settings</h2><p class="muted">Owner-controlled settings, stored in Supabase.</p><form id="settings" class="formgrid">'+[['company_name','Company name'],['time_zone','Time zone'],['workday_start','Workday start'],['workday_end','Workday end'],['grace_minutes','Grace minutes'],['currency','Default currency']].map(([key,label])=>'<div class="field"><label>'+label+'</label><input name="'+key+'" value="'+esc(x?.[key]||'')+'" '+(['grace_minutes'].includes(key)?'type="number"':'')+' required></div>').join('')+'<div class="field"><label>Minimum shift minutes</label><input name="minimum_shift_minutes" type="number" min="0" max="1440" value="'+esc((D.attendance_policies||[])[0]?.minimum_shift_minutes??60)+'"></div><div class="field"><label>Overtime threshold (minutes)</label><input name="overtime_after_minutes" type="number" min="0" max="1440" value="'+esc((D.attendance_policies||[])[0]?.overtime_after_minutes??480)+'"></div><div class="field"><label>Overtime reporting</label><select name="overtime_enabled"><option value="false">Off</option><option value="true" '+((D.attendance_policies||[])[0]?.overtime_enabled?'selected':'')+'>On</option></select></div><button class="settings-save" type="submit">Save settings</button></form></div>'}
function smsSettingsPanel(){let p=D.employee_alert_preferences?.[0]||{},valid=/^\+[1-9][0-9]{7,14}$/.test(String(me.phone||'').trim());return '<section class="panel"><div class="panelhead"><div><h2>Attendance SMS alerts</h2><p class="muted small">Optional check-in and check-out text alerts to your registered mobile number.</p></div></div><p>Registered mobile: <b>'+esc(me.phone||'Not registered')+'</b> '+(valid?'':'<small class="muted">(HR must enter an international number, such as +91...)</small>')+'</p><label class="confirm-check"><input id="smsOptIn" type="checkbox" '+(p.attendance_sms?'checked':'')+' '+(valid?'':'disabled')+'><span>I consent to receive attendance SMS messages on my registered mobile number.</span></label><div class="actionrow"><button id="saveSmsOptIn" class="white" '+(valid?'':'disabled')+'>Save preference</button><button id="smsCheck" class="white">Check SMS availability</button></div><p class="muted small">SMS sending requires the platform SMS provider to be configured. Your GPS coordinates are never included in these text messages. Attendance is recorded even if SMS delivery is unavailable.</p></section>'}
async function smsCall(action,values={}){const{data:{session}}=await db.auth.getSession();if(!session)throw Error('Sign in again');let res=await fetch(config.url+'/functions/v1/attendance-sms',{method:'POST',headers:{authorization:'Bearer '+session.access_token,apikey:config.key,'content-type':'application/json'},body:JSON.stringify({action,...values})});let data=await res.json();if(!res.ok)throw Error(data.error||'SMS service error');return data}
async function saveSmsOptIn(){let wanted=!!$('smsOptIn')?.checked;if(wanted&&!confirm('Allow attendance text messages to your registered mobile number? Standard carrier charges may apply.'))return;let row={user_id:me.user_id,organization_id:me.organization_id,attendance_sms:wanted,attendance_email:true,consented_at:wanted?new Date().toISOString():null,updated_at:new Date().toISOString()};let{error}=await db.from('employee_alert_preferences').upsert(row,{onConflict:'user_id'});if(error)throw error;notify(wanted?'SMS attendance opt-in saved. Delivery requires an active SMS provider.':'SMS alerts turned off.');await reload()}
async function attemptSmsNotification(attendanceId,eventType){if(!D.employee_alert_preferences?.some(x=>x.user_id===me.user_id&&x.attendance_sms))return;try{let result=await smsCall('notify',{attendance_id:attendanceId,event_type:eventType});if(result.sent)notify('Attendance SMS submitted to provider.');else if(result.reason==='sms_provider_not_configured')notify('Attendance saved. SMS provider is not configured.',true);else if(result.reason==='employee_phone_must_be_e164')notify('Attendance saved. Ask HR to correct your mobile number.',true)}catch(e){notify('Attendance saved. SMS notification could not be submitted.',true)}}
function profile(){const p=me,code=p.employee_code||'Not assigned',initial=String(p.full_name||'E').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const items=[['Employee ID',code],['Department',p.department],['Designation',p.job_title],['Employment type',fmt(p.employment_type)],['Date joined',p.joined_on],['Work location',p.work_location],['Phone',p.phone],['Reporting manager',p.manager_id?name(p.manager_id):'Not assigned'],['Email address',p.email],['Access role',fmt(p.role)]];return '<div class="profile-hero"><div class="profile-photo">'+esc(initial)+'</div><div class="profile-meta"><h2>'+esc(p.full_name)+'</h2><p>'+esc(p.job_title)+' · '+esc(p.department)+'</p>'+tag(p.active?'Active':'Inactive')+' <span class="muted small" style="margin-left:10px">Employee code: '+esc(code)+'</span></div></div><div class="split"><section class="panel" style="margin-top:0"><div class="panelhead"><h2>Employment information</h2><span class="tag">Verified account</span></div><div class="profile-info">'+items.map(([label,v])=>'<div class="profile-cell"><label>'+esc(label)+'</label><strong>'+esc(v||'—')+'</strong></div>').join('')+'</div></section><section class="panel" style="margin-top:0"><div class="panelhead"><h2>My workspace summary</h2></div><div class="metric-list"><div class="boxline"><span class="muted">Tasks assigned</span><strong>'+D.tasks.filter(t=>t.assigned_to===p.user_id).length+'</strong></div><div class="boxline"><span class="muted">Attendance records</span><strong>'+D.attendance.filter(a=>a.user_id===p.user_id).length+'</strong></div><div class="boxline"><span class="muted">Leave requests</span><strong>'+D.leave_requests.filter(l=>l.user_id===p.user_id).length+'</strong></div><div class="boxline"><span class="muted">Expense claims</span><strong>'+D.expense_claims.filter(x=>x.user_id===p.user_id).length+'</strong></div></div><p class="muted small" style="margin-top:20px">Profile changes are managed by your organisation administrator. Use the employee directory to edit permitted details.</p></section></div>'+smsSettingsPanel()}

function navigateTo(target){
if(target==='Platform'||!permitted(target))return;
const sidebar=document.querySelector('#sideNav');
const previousSidebarScroll=sidebar?sidebar.scrollTop:0;
tab=target;search='';filter='all';
render();
const nextSidebar=document.querySelector('#sideNav');
if(nextSidebar)nextSidebar.scrollTop=previousSidebarScroll;
const pane=document.querySelector('.content');
if(pane)pane.scrollTop=0;
document.querySelector('#appLayout')?.classList.remove('menu-open');
window.scrollTo(0,0);
}


async function loadSupportData(){
D.support_threads=[];D.support_messages=[];
if(!(platformAdmin||isStaff()))return;
const {data:threads,error}=await db.from('support_threads').select('id,organization_id,subject,status,created_at,updated_at').order('updated_at',{ascending:false}).limit(200);
if(error)throw error;
D.support_threads=threads||[];
const ids=D.support_threads.map(t=>t.id);
if(!ids.length){supportSelectedId=null;return}
if(!supportSelectedId||!ids.includes(supportSelectedId))supportSelectedId=ids[0];
const {data:msgs,error:msgError}=await db.from('support_messages').select('id,thread_id,sender_id,message,created_at').in('thread_id',ids).order('created_at',{ascending:false}).limit(500);
if(msgError)throw msgError;
D.support_messages=(msgs||[]).reverse();
}
function supportConsole(){
const provider=platformAdmin&&workspaceMode==='platform';
const threads=(D.support_threads||[]).filter(t=>provider||t.organization_id===me.organization_id);
const selected=threads.find(t=>t.id===supportSelectedId)||threads[0]||null;
if(selected)supportSelectedId=selected.id;
const company=id=>(D.organizations||[]).find(o=>o.id===id)?.name||'Customer company';
const chooser=provider?'<div class="support-thread-list">'+(threads.length?threads.map(t=>'<button class="support-thread '+(selected?.id===t.id?'selected':'')+'" data-open-thread="'+esc(t.id)+'"><strong>'+esc(company(t.organization_id))+'</strong><small>'+esc(t.status)+' · '+esc(stamp(t.updated_at))+'</small></button>').join(''):'<div class="empty">No company conversations yet.</div>')+'</div>':'';
const msgs=selected?(D.support_messages||[]).filter(m=>m.thread_id===selected.id):[];
const transcript='<div class="support-transcript">'+(msgs.length?msgs.map(m=>'<div class="support-message '+(m.sender_id===me.user_id?'mine':'')+'"><div class="support-message-author">'+esc(m.sender_id===me.user_id?'You':provider?'Company administrator':'PeopleOS Support')+' · '+esc(stamp(m.created_at))+'</div><p>'+esc(m.message)+'</p></div>').join(''):'<div class="empty">No messages yet.</div>')+'</div>';
const allowed=selected||(!provider&&isStaff());
const compose=allowed?'<form id="supportSend" class="support-compose"><textarea name="message" maxlength="3000" rows="3" placeholder="Write a support message..." required></textarea><button type="submit">Send message</button></form>':'';
return '<section class="panel"><div class="panelhead"><div><h2>'+(provider?'Customer support inbox':'Contact PeopleOS Support')+'</h2><p class="muted small">'+(provider?'Messages from customer company administrators':'Private messages between your company administrators and the software provider.')+'</p></div><button id="supportRefresh" class="white">Refresh messages</button></div><div class="support-layout">'+chooser+'<div class="support-detail"><h3>'+(selected?esc(provider?company(selected.organization_id):'Company support chat'):'Support messages')+'</h3>'+transcript+compose+'</div></div></section>';
}
async function sendSupportMessage(ev){
ev.preventDefault();
const form=ev.currentTarget,button=form.querySelector('button[type=submit]'),message=String(new FormData(form).get('message')||'').trim();
if(message.length<1||message.length>3000){notify('Message must be 1–3000 characters',true);return}
button.disabled=true;
try{
let thread=(D.support_threads||[]).find(t=>t.id===supportSelectedId);
if(!thread||!(platformAdmin&&workspaceMode==='platform')&&thread.organization_id!==me.organization_id){
if(platformAdmin&&workspaceMode==='platform')throw Error('Select a company conversation');
const {data:existing,error:readError}=await db.from('support_threads').select('id').eq('organization_id',me.organization_id).maybeSingle();
if(readError)throw readError;
if(existing)thread=existing;
else{
const {data,error}=await db.from('support_threads').insert({organization_id:me.organization_id}).select('id').single();
if(error)throw error;
thread=data;
}
}
const {data:{user}}=await db.auth.getUser();if(!user)throw Error('Session expired');
const {error}=await db.from('support_messages').insert({thread_id:thread.id,sender_id:user.id,message});
if(error)throw error;
supportSelectedId=thread.id;await loadSupportData();render();notify('Message sent');
}catch(err){notify(err.message,true)}finally{button.disabled=false}
}

function weekMonday(date){
const d=new Date((date||localDate())+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);
}
function shiftDay(date,delta){
const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10);
}
function moveRosterWeek(n){rosterWeek=shiftDay(weekMonday(rosterWeek),n);render()}
function rosterView(){
const start=weekMonday(rosterWeek),days=Array.from({length:7},(_,i)=>shiftDay(start,i)),staff=isStaff();
const people=(D.profiles||[]).filter(p=>p.active&&(staff||p.user_id===me.user_id)).sort((a,b)=>a.full_name.localeCompare(b.full_name));
const shifts=(D.work_shifts||[]).filter(s=>days.includes(s.shift_date)),scheduled=shifts.filter(s=>s.status!=='cancelled');
const header=days.map(d=>'<th>'+esc(new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{timeZone:'UTC',weekday:'short',day:'numeric',month:'short'}))+'</th>').join('');
const rows=people.map(p=>'<tr><th class="roster-person">'+esc(p.full_name)+'<small>'+esc(p.department||'')+'</small></th>'+days.map(d=>{
const s=shifts.find(x=>x.user_id===p.user_id&&x.shift_date===d);
const display=s?'<b>'+esc((s.starts_at||'').slice(0,5))+' – '+esc((s.ends_at||'').slice(0,5))+'</b><small>'+esc(s.status)+(s.location?' · '+esc(s.location):'')+'</small>':'<small>Not scheduled</small>';
return '<td>'+(staff?'<button class="roster-entry" data-roster-user="'+esc(p.user_id)+'" data-roster-date="'+esc(d)+'">'+display+'</button>':'<div class="roster-entry readonly">'+display+'</div>')+'</td>';
}).join('')+'</tr>').join('');
return '<section class="panel"><div class="panelhead"><div><h2>Weekly Roster</h2><p class="muted small">Work schedules for '+esc(start)+' through '+esc(days[6])+'. HR can assign shifts, employees can view their own roster.</p></div><div class="actionrow"><button class="white" id="rosterPrev">Previous</button><input id="rosterDate" type="date" aria-label="Select week" value="'+esc(rosterWeek||localDate())+'"><button class="white" id="rosterToday">This week</button><button class="white" id="rosterNext">Next</button>'+(staff?'<button id="rosterAdd">+ Assign shift</button>':'')+'</div></div>'+
'<div class="roster-summary"><span>'+people.length+' employees</span><span>'+scheduled.length+' scheduled shifts</span><span>'+new Set(scheduled.map(s=>s.user_id)).size+' people scheduled</span></div>'+
'<div class="roster-overflow"><table class="roster-table"><thead><tr><th>Employee</th>'+header+'</tr></thead><tbody>'+(rows||'<tr><td colspan="8" class="empty">No active employees</td></tr>')+'</tbody></table></div><p class="muted small">Schedules are stored in Supabase. Approved leave dates cannot be assigned new shifts.</p></section>';
}
function editRoster(userId,date){
if(!isStaff())return;
const previous=(D.work_shifts||[]).find(s=>s.user_id===userId&&s.shift_date===date);
const initial=previous||{user_id:userId||'',shift_date:date||localDate(),starts_at:'09:00',ends_at:'18:00',status:'scheduled'};
modal(previous?'Edit shift':'Assign shift','<form>'+fieldsHtml('Shifts',initial)+'<p class="muted small">Choose Cancelled to preserve a cancelled assignment in the schedule history.</p><button type="submit">'+(previous?'Save shift':'Assign shift')+'</button></form>',async v=>{
if(!v.user_id||!v.shift_date||!v.starts_at||!v.ends_at||v.starts_at===v.ends_at)throw Error('Employee, date and valid start/end times are required');
if(previous)await patch('Shifts',previous.id,v);
else await create('Shifts',v);
});
}
function roleAccessGuide(){if(me.role!=='owner')return '<div class="panel"><h2>Restricted company management</h2><p>You do not have access to manage organization role permissions.</p></div>';let role=me.role,headings={owner:'Company Owner',hr:'Human Resources',manager:'Manager',team_leader:'Team Leader',employee:'Employee'},matrix=[
['Personal attendance & breaks','Record check-in, breaks, checkout and request corrections',['owner','hr','manager','team_leader','employee']],
['My leave and claims','Request leave, track balances and submit expense proof',['owner','hr','manager','team_leader','employee']],
['My tasks','See assigned work and update your own task progress',['owner','hr','manager','team_leader','employee']],
['Team directory','See relevant company staff or your reporting team',['owner','hr','manager','team_leader']],
['Assign team tasks','Create and assign tasks to employees you manage',['owner','hr','manager','team_leader']],
['Approve team leave','Approve or reject pending requests within reporting scope',['owner','hr','manager']],
['Recruitment & onboarding','Manage candidates, hiring and onboarding',['owner','hr']],
['Employee records','Manage allowed personnel details; role changes require the owner',['owner','hr']],
['Employee role assignment','Promote staff or change access roles',['owner']],
['Payroll administration','Set salary templates, run payroll and review payslips',['owner','hr']],
['Payslip company branding','Select templates and upload official logo or seal',['owner']],
['Organization settings','Configure company-wide work schedules and policies',['owner']],
['Company email setup','Configure verified organization email sender',['owner']],
['Audit and organization activity','Review operational audit records',['owner']]
];let permitted=matrix.filter(x=>x[2].includes(role)),restricted=matrix.filter(x=>!x[2].includes(role));const rows=list=>list.map(x=>'<div class="access-line"><span class="access-symbol">'+(x[2].includes(role)?'✓':'—')+'</span><div><strong>'+esc(x[0])+'</strong><p>'+esc(x[1])+'</p></div></div>').join('');return '<section class="access-summary"><div><small>YOUR ROLE</small><h2>'+esc(headings[role]||fmt(role))+'</h2><p>Permissions are applied to your company and employee reporting structure. This guide describes standard access; company features and approval rules may reduce available actions.</p></div><div class="access-number"><b>'+permitted.length+'</b><small>available capabilities</small></div></section><div class="access-columns"><section class="panel"><h2>What you can do</h2>'+rows(permitted)+'</section><section class="panel"><h2>Restricted responsibilities</h2>'+rows(restricted)+'</section></div><section class="panel"><h2>How access is controlled</h2><p class="muted">Company owners control staff roles and company settings. HR manages people and payroll but cannot change roles or edit the owner profile. Managers and team leaders see their reporting teams, not other departments’ private records. Employees see their own personal records and released payslips. Platform administrators manage company provisioning separately from ordinary company accounts.</p><p class="muted small">Actual access is checked by the database and service permissions, not only the menus shown here.</p></section>'}
function render(){if(!me)return;frame(tab==='Support'?supportConsole():tab==='Roster'?rosterView():tab==='Overview'?dash():tab==='Notifications'?notificationsPage():tab==='Company Mail'?companyMailPage():tab==='Reports'?report():tab==='My Profile'?profile():tab==='My Access'?roleAccessGuide():tab==='Settings'?settings():genericPage());bind()}

function editEmployeeProfile(id){
const p=(D.profiles||[]).find(x=>x.user_id===id);if(!p)return;
const f=(k,label,type='text')=>'<div class="field"><label>'+esc(label)+'</label><input name="'+k+'" type="'+type+'" value="'+esc(p[k]??'')+'"></div>';
const managers=(D.profiles||[]).filter(x=>x.active&&x.user_id!==id&&['owner','hr','manager','team_leader'].includes(x.role)&&(p.role==='employee'||x.role!=='team_leader'));
const manager='<div class="field"><label>Reporting manager</label><select name="manager_id"><option value="">None</option>'+managers.map(x=>'<option value="'+esc(x.user_id)+'" '+(p.manager_id===x.user_id?'selected':'')+'>'+esc(x.full_name)+'</option>').join('')+'</select></div>';
const role=me.role==='owner'?'<div class="field"><label>Role</label><select name="role">'+['employee','team_leader','manager','hr',...(p.role==='owner'?['owner']:[])].map(k=>'<option value="'+k+'" '+(p.role===k?'selected':'')+'>'+esc(fmt(k))+'</option>').join('')+'</select></div>':'';
modal('Edit employee — '+p.full_name,'<form><div class="formgrid">'+f('full_name','Full name')+f('employee_code','Employee code')+f('department','Department')+f('job_title','Job title')+f('phone','Phone')+f('work_location','Work location')+f('joined_on','Joined date','date')+manager+role+'</div><button type="submit">Save employee</button></form>',async v=>{let values={full_name:v.full_name.trim(),employee_code:v.employee_code||null,department:v.department,job_title:v.job_title,phone:v.phone||null,work_location:v.work_location||null,joined_on:v.joined_on||null,manager_id:v.manager_id||null};if(me.role==='owner'&&v.role)values.role=v.role;if(!values.full_name)throw Error('Name required');await patch('Employees',id,values)});
}
function fieldsHtml(t,record={}){let attrs=t==='Employees'?[['full_name','Full name'],['email','Email','email'],['department','Department'],['job_title','Job title'],['role','Role','select:employee,team_leader,manager,hr']]:fields[t]||[];return '<div class="formgrid">'+attrs.map(([k,label,type])=>{let v=record[k]??'';if(type==='datetime-local'&&v){let d=new Date(v);if(!isNaN(d)){let z=n=>String(n).padStart(2,'0');v=d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate())+'T'+z(d.getHours())+':'+z(d.getMinutes())}}let box=type?.startsWith('select:')?'<select name="'+k+'"><option value="">Choose…</option>'+type.slice(7).split(',').map(x=>'<option '+(String(v)===x?'selected':'')+' value="'+x+'">'+x+'</option>').join('')+'</select>':type==='candidate'?'<select name="'+k+'"><option value="">Select candidate</option>'+(D.candidates||[]).map(p=>'<option value="'+esc(p.id)+'" '+(v===p.id?'selected':'')+'>'+esc(p.full_name)+'</option>').join('')+'</select>':type==='jobOptional'?'<select name="'+k+'"><option value="">Unlinked</option>'+(D.job_openings||[]).map(p=>'<option value="'+esc(p.id)+'" '+(v===p.id?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select>':type==='managerOptional'?'<select name="'+k+'"><option value="">Unassigned</option>'+(D.profiles||[]).filter(p=>p.active&&['owner','hr','manager'].includes(p.role)).map(p=>'<option value="'+esc(p.user_id)+'" '+(v===p.user_id?'selected':'')+'>'+esc(p.full_name)+'</option>').join('')+'</select>':type==='user'||type==='userOptional'?'<select name="'+k+'">'+(type==='userOptional'?'<option value="">Unassigned</option>':'<option value="">Select employee</option>')+D.profiles.filter(x=>x.active).map(p=>'<option value="'+esc(p.user_id)+'" '+(v===p.user_id?'selected':'')+'>'+esc(p.full_name)+'</option>').join('')+'</select>':type==='textarea'?'<textarea name="'+k+'">'+esc(v)+'</textarea>':'<input name="'+k+'" type="'+(type||'text')+'" '+(type==='number'?'step="any"':'')+' value="'+esc(v)+'" '+(k==='email'||k==='full_name'||k==='title'||k==='reason'?'required':'')+'>';return '<div class="field"><label>'+esc(label)+'</label>'+box+'</div>'}).join('')+'</div>'}
function modal(title,content,handler){let div=document.createElement('div');div.className='overlay';div.innerHTML='<div class="dialog"><div class="dialoghead"><h2>'+esc(title)+'</h2><button id="close">×</button></div>'+content+'</div>';document.body.append(div);div.querySelector('#close').onclick=()=>div.remove();div.onclick=e=>{if(e.target===div)div.remove()};let form=div.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();let b=form.querySelector('button[type=submit]');if(b)b.disabled=true;try{await handler(Object.fromEntries(new FormData(form)));div.remove();await reload();notify('Saved successfully')}catch(err){notify(err.message,true)}finally{if(b)b.disabled=false}}}
function previewInvitation(v){
return new Promise(resolve=>{
const company=D.company_settings?.[0]?.company_name||'PeopleOS',url='https://peopleos-next-production.up.railway.app';
let div=document.createElement('div');div.className='overlay';
div.innerHTML='<div class="dialog"><div class="dialoghead"><h2>Invitation preview</h2><button id="invClose">×</button></div><p class="muted small">Preview of the intended welcome message. Actual email branding depends on the configured Supabase email template and SMTP sender.</p><div style="padding:22px;margin:14px 0;border:1px solid #e0e7f2;border-radius:12px"><small>Subject: Welcome to '+esc(company)+' — Activate your account</small><h2 style="margin:17px 0">Welcome to '+esc(company)+'</h2><p>Hello '+esc(v.full_name)+',</p><p>You have been invited to the '+esc(company)+' HRMS as '+esc(v.job_title||'an employee')+'.</p><p>Open the secure invitation link you receive by email to verify your account and create a password.</p><p>HRMS login: <a href="'+url+'" target="_blank" rel="noopener noreferrer">'+url+'</a></p><p>Regards,<br>'+esc(company)+' HR Team</p></div><div class="actionrow"><button class="white" id="invCancel">Cancel</button><button id="invSend">Request invitation</button></div></div>';document.body.append(div);
const done=v=>{div.remove();resolve(v)};
div.querySelector('#invClose').onclick=()=>done(false);div.querySelector('#invCancel').onclick=()=>done(false);div.querySelector('#invSend').onclick=()=>done(true);
});
}
async function create(t,v){if(t==='Expenses'){let file=proofFile(v.receipt_file);delete v.receipt_file;v.user_id=me.user_id;v.amount=Number(v.amount);if(!Number.isFinite(v.amount)||v.amount<=0)throw Error('Invalid expense amount');Object.keys(v).forEach(k=>{if(v[k]==='')delete v[k]});let{data,error}=await db.from('expense_claims').insert(v).select('id').single();if(error)throw error;if(file)try{await uploadProof(file,data.id)}catch(e){throw Error('Expense saved without proof. Open the pending expense to retry. '+e.message)}return}if(t==='Employees'){if(!await previewInvitation(v))return;const {data:{session}}=await db.auth.getSession();const res=await fetch(config.url+'/functions/v1/invite-employee',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,apikey:config.key,'content-type':'application/json'},body:JSON.stringify(v)});let result=await res.json();if(!res.ok)throw Error(result.error||'Unable to invite');notify('Invitation accepted by the authentication service for '+v.email+'. Delivery depends on email configuration.');return}const table=tables[t];if(['Corrections','Leave','Expenses'].includes(t))v.user_id=me.user_id;if(t==='Recruitment')v.headcount=Number(v.headcount||1);if(t==='Candidates')v.job_id=v.job_id||null;if(t==='Interviews'){v.interviewer_id=v.interviewer_id||null;v.duration_minutes=Number(v.duration_minutes||30);if(v.scheduled_at)v.scheduled_at=new Date(v.scheduled_at).toISOString()}if(t==='Tasks')v.created_by=me.user_id;if(t==='Announcements')v.author_id=me.user_id;if(t==='Payroll'){v.month+='-01';v.basic=Number(v.basic);v.allowances=Number(v.allowances||0);v.deductions=Number(v.deductions||0)}if(t==='Balances'){v.days=Number(v.days);v.calendar_year=Number(v.calendar_year)}if(t==='Expenses')v.amount=Number(v.amount);if(t==='Reviews')v.rating=Number(v.rating||0)||null;if(t==='Corrections')for(let k of ['requested_check_in','requested_check_out'])v[k]=v[k]?new Date(v[k]).toISOString():null;if(t==='Assets'&&!v.assigned_to)v.assigned_to=null;if(t==='Announcements')v.published=v.published!=='false';Object.keys(v).forEach(k=>{if(v[k]==='')delete v[k]});const{error}=await db.from(table).insert(v);if(error)throw error}
