function csv(t){let H=cols[t]||[],R=D[tables[t]]||[],L=D.attendance_locations||[],S=D.attendance_shift_summary||[],q=v=>'"'+String(v??'').replace(/[\r\n]+/g,' ').replace(/^([=+@-])/,"'$1").replaceAll('"','""')+'"',v=(r,k)=>{if(k==='check_in'||k==='check_out')return r[k]?stamp(r[k]):'';if(k==='hours')return r.check_out&&r.check_in?((new Date(r.check_out)-new Date(r.check_in))/36e5).toFixed(2):'';if(k==='net_hours'||k==='break_minutes'){let a=S.find(x=>x.id===r.id),v=(D.attendance_net_summary||[]).find(x=>x.id===r.id);return k==='net_hours'?(v?(Number(v.net_worked_minutes||0)/60).toFixed(2):''):(v?.break_minutes??'')}if(k==='shift_assessment')return S.find(x=>x.id===r.id)?.arrival_status||'';if(k.startsWith('location_')){let x=L.find(x=>x.attendance_id===r.id&&x.event_type===(k==='location_in'?'check_in':'check_out'));return x?[x.area_name,x.city_name,x.latitude+','+x.longitude,'±'+Math.round(x.accuracy_m)+'m'].filter(Boolean).join(' | '):''}return k.endsWith('_id')?name(r[k]):r[k]};if(t==='Attendance'&&dateRange!=='all'){let cut=new Date(Date.now()-Number(dateRange)*864e5).toISOString().slice(0,10);R=R.filter(x=>x.work_date>=cut)}let data='\ufeff'+[H.map(x=>q(x[1])),...R.map(r=>H.map(x=>q(v(r,x[0]))))].map(x=>x.join(',')).join('\r\n'),u=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='peopleos-'+t.toLowerCase()+'-'+localDate()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function reverseFreshGPS(g){try{const r=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+encodeURIComponent(g.latitude)+'&longitude='+encodeURIComponent(g.longitude)+'&localityLanguage=en');if(!r.ok)throw Error('Area unavailable');const a=await r.json(),s=x=>typeof x==='string'?x.slice(0,110):'';return {area:s(a.locality||a.localityName||a.city),city:s(a.city||a.locality||a.localityName),region:s(a.principalSubdivision),country:s(a.countryName)}}catch(e){return {area:'',city:'',region:'',country:''}}}
async function attendanceGPS(){
if(!window.isSecureContext||!navigator.geolocation)throw Error('Location attendance requires a supported HTTPS browser with location access enabled.');
return new Promise((resolve,reject)=>{
navigator.geolocation.getCurrentPosition(
pos=>{
const latitude=Number(pos.coords.latitude),longitude=Number(pos.coords.longitude),accuracy=Number(pos.coords.accuracy);
if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||!Number.isFinite(accuracy)||accuracy>5000||accuracy<0){reject(new Error('GPS location accuracy is insufficient. Try again outdoors or with location enabled.'));return}
resolve({latitude,longitude,accuracy});
},
err=>reject(new Error(err.code===1?'Location permission was denied. Enable location for this site to record a GPS attendance punch.':err.code===3?'Location request timed out. Try again with location services enabled.':'Unable to determine your location. Check your device settings and try again.')),
{enableHighAccuracy:true,timeout:18000,maximumAge:0}
);
});
}
async function confirmAttendance(){
const button=$('clock');if(button)button.disabled=true;
try{
const {data:recent,error:e}=await db.from('attendance').select('id,check_in,check_out,work_date').eq('user_id',me.user_id).eq('work_date',localDate()).maybeSingle();
if(e)throw e;
if(recent?.check_out){notify('Your attendance has already been completed today.');await reload();return;}
const action=recent?.check_in?'check_out':'check_in';
const label=action==='check_in'?'Check in':'Check out';
const heading=action==='check_in'?'Confirm start of your workday':'Confirm end of your workday';
const note=action==='check_in'?'This will create your first attendance entry for today.':'This will finish your recorded shift for today. It cannot be undone by clicking again.';
const markup='<form><div class="attend-confirm"><strong>'+heading+'</strong><small>Employee: '+esc(me.full_name)+'<br>Attendance date: '+esc(localDate())+'<br>Time is recorded by the server.<br>'+note+'</small></div><div class="geo-consent"><strong>Location-based attendance</strong><p>This punch will capture your device location once, including approximate GPS accuracy and a server timestamp. It can be viewed by you and your company Owner/HR. It does not track you continuously. With your consent, the current GPS point is also shared with a third-party location service to identify an approximate area and city. Allow location access in your browser when prompted.</p></div><label class="confirm-check"><input id="acknowledgeAttendance" type="checkbox" required><span>I understand and agree to share my current location for this attendance punch.</span></label><div class="actionrow"><button class="white" type="button" id="cancelAttendance">Cancel</button><button type="submit" id="submitAttendance" disabled>Confirm '+label+'</button></div></form>';
modal(heading,markup,async()=>{
const gps=await attendanceGPS();const place=await reverseFreshGPS(gps);const {data:attendanceRecord,error:rpcError}=await db.rpc('record_attendance_with_location',{p_action:action,p_latitude:gps.latitude,p_longitude:gps.longitude,p_accuracy_m:gps.accuracy,p_area:place.area,p_city:place.city,p_region:place.region,p_country:place.country});
if(rpcError)throw rpcError;
notify(label+' recorded successfully.');if(attendanceRecord?.id)attemptSmsNotification(attendanceRecord.id,action);
});
const overlay=document.querySelector('.overlay:last-of-type');
if(overlay){
const cb=overlay.querySelector('#acknowledgeAttendance'),submit=overlay.querySelector('#submitAttendance');
if(cb&&submit)cb.onchange=()=>submit.disabled=!cb.checked;
const cancel=overlay.querySelector('#cancelAttendance');
if(cancel)cancel.onclick=()=>overlay.remove();
}
}catch(ex){notify(ex.message||String(ex),true)}finally{if(button&&button.isConnected)button.disabled=false;}
}

